// Converte o texto em Markdown que chega em $json.output para HTML básico
// Saída: { html: "<!doctype html>... </html>" }

const md = ($json.output ?? '').toString();

// 1) Escapa HTML bruto para evitar quebras
function escapeHtml(s) {
  return s.replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');
}
let html = escapeHtml(md);

// 2) Títulos (#, ##, ### ...)
html = html
  .replace(/^###### (.*)$/gm, '<h6>$1</h6>')
  .replace(/^##### (.*)$/gm, '<h5>$1</h5>')
  .replace(/^#### (.*)$/gm,  '<h4>$1</h4>')
  .replace(/^### (.*)$/gm,   '<h3>$1</h3>')
  .replace(/^## (.*)$/gm,    '<h2>$1</h2>')
  .replace(/^# (.*)$/gm,     '<h1>$1</h1>');

// 3) Negrito e itálico (**texto**, *texto*)
html = html
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  // itálico com cuidado para não pegar * em listas
  .replace(/(^|[\s(])\*(?!\s)(.+?)(?<!\s)\*(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>');

// 4) Constrói listas e parágrafos
const lines = html.split(/\r?\n/);
let out = [];
let inUl = false, inOl = false;

function closeLists() {
  if (inUl) { out.push('</ul>'); inUl = false; }
  if (inOl) { out.push('</ol>'); inOl = false; }
}

for (const line of lines) {
  let m;
  if ((m = line.match(/^\s*[-•*]\s+(.*)$/))) {
    if (inOl) { out.push('</ol>'); inOl = false; }
    if (!inUl) { out.push('<ul>'); inUl = true; }
    out.push(`<li>${m[1]}</li>`);
  } else if ((m = line.match(/^\s*\d+\.\s+(.*)$/))) {
    if (inUl) { out.push('</ul>'); inUl = false; }
    if (!inOl) { out.push('<ol>'); inOl = true; }
    out.push(`<li>${m[1]}</li>`);
  } else {
    closeLists();
    if (line.trim() === '') {
      out.push('<br/>');
    } else {
      out.push(`<p>${line}</p>`);
    }
  }
}
closeLists();

const body = out.join('\n');

// 5) HTML final com estilo simples (bom para conversão a DOCX)
const fullHtml = `<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8">
  <style>
    body{font-family: Arial, Helvetica, sans-serif; line-height:1.38; color:#111; margin:24px;}
    h1{font-size:20pt;margin:0 0 8px} h2{font-size:16pt;margin:16px 0 6px} h3{font-size:13pt;margin:14px 0 6px}
    h4,h5,h6{margin:12px 0 6px}
    p{margin:6px 0}
    ul,ol{margin:6px 0 12px 22px} li{margin:2px 0}
    strong{font-weight:700} em{font-style:italic}
    table{border-collapse:collapse;margin:8px 0;width:100%}
    th,td{border:1px solid #ccc;padding:6px;vertical-align:top}
  </style>
</head>
<body>
${body}
</body>
</html>`;

return [{ json: { html: fullHtml } }];

// Junta o markdown das paginas retornadas pelo Mistral OCR
function joinPages(resp) {
  const pages = (resp && resp.pages) || [];
  return pages.map(p => (p && p.markdown) ? p.markdown : '').join('\n\n').trim();
}

const body   = $('Webhook').item.json.body || {};
const modelo = $('Buscar modelo').item.json || {};

const textoCliente = joinPages($('OCR Cliente').item.json);

// Modelo: usa o cache (texto_extraido) quando existe; senao usa o OCR Modelo.
// O ramo do OCR pode nao ter executado nesta run (cache hit) -> try/catch.
let textoModelo = (modelo.texto_extraido && modelo.texto_extraido.trim())
  ? modelo.texto_extraido.trim()
  : '';
if (!textoModelo) {
  try { textoModelo = joinPages($('OCR Modelo').item.json); } catch (e) { textoModelo = ''; }
}

if (!textoCliente) { throw new Error('OCR do contrato do cliente veio vazio.'); }
if (!textoModelo)  { throw new Error('Texto do modelo vazio (sem cache e sem OCR).'); }

return [{
  json: {
    contratoId:    body.contratoId,
    tipoDocumento: body.tipoDocumento || '',
    modeloNome:    modelo.nome || body.modeloNome || 'Modelo Padrao BMS',
    origemModelo:  textoModelo === (modelo.texto_extraido || '').trim() ? 'cache' : 'ocr',
    textoModelo,
    textoCliente
  }
}];

// ---- 1) Recupera e limpa a saida do agente ----
let raw = ($('Assistente Juridico').item.json.output || '').toString().trim();

// remove cercas ```json ... ```
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

// pega do primeiro { ao ultimo } (caso venha algum texto ao redor)
const ini = raw.indexOf('{');
const fim = raw.lastIndexOf('}');
if (ini !== -1 && fim !== -1) { raw = raw.slice(ini, fim + 1); }

let dados;
try {
  dados = JSON.parse(raw);
} catch (e) {
  throw new Error('Falha ao interpretar JSON do agente: ' + e.message + '\n\nInicio da resposta:\n' + raw.slice(0, 500));
}

const modeloNome = $('Montar contexto').item.json.modeloNome || 'Modelo Padrao BMS';
const divs      = Array.isArray(dados.divergencias) ? dados.divergencias : [];
const ausentes  = Array.isArray(dados.clausulas_ausentes) ? dados.clausulas_ausentes : [];

// ---- 2) Helpers ----
const ORDEM_SEV = { 'CRITICA': 0, 'CRÍTICA': 0, 'ALTA': 1, 'MEDIA': 2, 'MÉDIA': 2, 'BAIXA': 3 };
function sevRank(s){ return ORDEM_SEV[(s||'').toUpperCase()] ?? 9; }
function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function bq(s){ // markdown blockquote
  return (s==null?'':String(s)).split('\n').map(l => '> ' + l).join('\n');
}
function resumoCel(s, n){ // resumo curto p/ tabela
  const t = (s==null?'':String(s)).replace(/\s+/g,' ').trim();
  const palavras = t.split(' ');
  return palavras.length > n ? palavras.slice(0, n).join(' ') + '...' : t;
}

// ---- 3) MARKDOWN (vai para contratos_analise.analise_ia / UI) ----
const md2 = [];
md2.push(`## Analise Comparativa de Contrato — ${modeloNome}`);
if (dados.resumo_executivo) { md2.push('', `> ${dados.resumo_executivo}`); }
md2.push('', '## 📚 Divergencias (analise clausula a clausula)');
if (divs.length === 0) { md2.push('', '_Nenhuma divergencia relevante identificada._'); }
divs.forEach((d, i) => {
  const num = d.numero || (i + 1);
  md2.push('', `### ${num}. ${d.tema || 'Divergencia'}${d.clausula ? ' — ' + d.clausula : ''}`);
  md2.push('', `**Severidade:** ${d.severidade || 'N/D'}  \n**Impacto:** ${d.impacto || 'N/D'}`);
  md2.push('', '**Modelo Padrao BMS:**', '', bq(d.trecho_modelo || '(nao consta no modelo)'));
  md2.push('', '**Contrato do Cliente:**', '', bq(d.trecho_cliente || '(nao consta no contrato do cliente)'));
  if (d.diferenca) { md2.push('', `**Diferenca:** ${d.diferenca}`); }
  if (d.sugestao_redacao) {
    md2.push('', bq(`💡 Sugestao de Redacao (Texto Final):\n"${d.sugestao_redacao}"` + (d.racional ? `\n\nRacional: ${d.racional}` : '')));
  }
});

// Clausulas ausentes
if (ausentes.length) {
  md2.push('', '## ⚠️ Clausulas do modelo ausentes no contrato do cliente');
  ausentes.forEach((a, i) => {
    md2.push('', `### A${i + 1}. ${a.clausula || 'Clausula ausente'}`);
    md2.push('', `**Severidade:** ${a.severidade || 'N/D'}`);
    md2.push('', '**Texto do Modelo Padrao BMS:**', '', bq(a.trecho_modelo || ''));
    if (a.sugestao_redacao) {
      md2.push('', bq(`💡 Sugestao de Redacao (Texto Final):\n"${a.sugestao_redacao}"` + (a.racional ? `\n\nRacional: ${a.racional}` : '')));
    }
  });
}

// Tabela resumo (top 10 por severidade)
const topo = divs.slice().sort((a, b) => sevRank(a.severidade) - sevRank(b.severidade)).slice(0, 10);
if (topo.length) {
  md2.push('', '## 📊 Resumo visual (prioridade por severidade)');
  md2.push('', '| Tema | Contrato do Cliente | Modelo BMS | Severidade | Impacto | Sugestao |');
  md2.push('| --- | --- | --- | --- | --- | --- |');
  topo.forEach(d => {
    md2.push(`| ${resumoCel(d.tema,8)} | ${resumoCel(d.trecho_cliente,15)} | ${resumoCel(d.trecho_modelo,15)} | ${d.severidade||'N/D'} | ${d.impacto||'N/D'} | ${resumoCel(d.sugestao_redacao,15)} |`);
  });
}
if (dados.observacoes) { md2.push('', `**Observacoes:** ${dados.observacoes}`); }
md2.push('', '> *Este relatorio tem carater informativo e nao substitui consulta juridica individualizada.*');

const analise_md = md2.join('\n');

// ---- 4) HTML (vai para o api2pdf) — construido direto dos dados ----
function sevColor(s){
  const k=(s||'').toUpperCase();
  if(k.indexOf('CRIT')===0||k.indexOf('CRÍT')===0) return '#B00020';
  if(k==='ALTA') return '#E8590C';
  if(k==='MEDIA'||k==='MÉDIA') return '#F59F00';
  return '#2F9E44';
}
let rows = '';
topo.forEach(d => {
  rows += `<tr><td>${esc(resumoCel(d.tema,8))}</td><td>${esc(resumoCel(d.trecho_cliente,15))}</td><td>${esc(resumoCel(d.trecho_modelo,15))}</td>`+
          `<td><span class="badge" style="background:${sevColor(d.severidade)}">${esc(d.severidade||'N/D')}</span></td>`+
          `<td>${esc(d.impacto||'N/D')}</td><td>${esc(resumoCel(d.sugestao_redacao,15))}</td></tr>`;
});

let blocos = '';
divs.forEach((d, i) => {
  const num = d.numero || (i + 1);
  blocos += `<section class="div">
    <h3>${num}. ${esc(d.tema||'Divergencia')}${d.clausula?' — '+esc(d.clausula):''}</h3>
    <p class="meta"><span class="badge" style="background:${sevColor(d.severidade)}">${esc(d.severidade||'N/D')}</span> <b>Impacto:</b> ${esc(d.impacto||'N/D')}</p>
    <p class="lbl">Modelo Padrao BMS:</p><blockquote>${esc(d.trecho_modelo||'(nao consta no modelo)').replace(/\n/g,'<br>')}</blockquote>
    <p class="lbl">Contrato do Cliente:</p><blockquote>${esc(d.trecho_cliente||'(nao consta no contrato do cliente)').replace(/\n/g,'<br>')}</blockquote>
    ${d.diferenca?`<p><b>Diferenca:</b> ${esc(d.diferenca)}</p>`:''}
    ${d.sugestao_redacao?`<div class="sug"><p class="sug-t">💡 Sugestao de Redacao (Texto Final)</p><p class="sug-c">"${esc(d.sugestao_redacao).replace(/\n/g,'<br>')}"</p>${d.racional?`<p class="sug-r"><i>Racional: ${esc(d.racional)}</i></p>`:''}</div>`:''}
  </section>`;
});

let ausentesHtml = '';
if (ausentes.length) {
  ausentesHtml = '<h2>⚠️ Clausulas do modelo ausentes no contrato do cliente</h2>';
  ausentes.forEach((a, i) => {
    ausentesHtml += `<section class="div">
      <h3>A${i+1}. ${esc(a.clausula||'Clausula ausente')}</h3>
      <p class="meta"><span class="badge" style="background:${sevColor(a.severidade)}">${esc(a.severidade||'N/D')}</span></p>
      <p class="lbl">Texto do Modelo Padrao BMS:</p><blockquote>${esc(a.trecho_modelo||'').replace(/\n/g,'<br>')}</blockquote>
      ${a.sugestao_redacao?`<div class="sug"><p class="sug-t">💡 Sugestao de Redacao (Texto Final)</p><p class="sug-c">"${esc(a.sugestao_redacao).replace(/\n/g,'<br>')}"</p>${a.racional?`<p class="sug-r"><i>Racional: ${esc(a.racional)}</i></p>`:''}</div>`:''}
    </section>`;
  });
}

const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">
<style>
 body{font-family:Arial,Helvetica,sans-serif;line-height:1.45;color:#111;margin:28px;}
 h1{color:#021D44;font-size:20pt;margin:0 0 4px} h2{color:#021D44;font-size:15pt;margin:22px 0 8px;border-bottom:2px solid #FF7F00;padding-bottom:3px}
 h3{font-size:12.5pt;margin:16px 0 4px;color:#021D44}
 .meta{margin:2px 0 8px;font-size:9.5pt;color:#444}
 .badge{color:#fff;padding:2px 8px;border-radius:10px;font-size:8.5pt;font-weight:700;letter-spacing:.3px}
 .lbl{font-weight:700;margin:8px 0 2px;font-size:10pt}
 blockquote{border-left:3px solid #ccc;background:#F2F5FA;margin:0;padding:8px 12px;font-size:10pt}
 .sug{border-left:4px solid #FF7F00;background:#FFF7EE;padding:10px 12px;margin:10px 0;border-radius:4px}
 .sug-t{font-weight:700;color:#E8590C;margin:0 0 4px} .sug-c{margin:0;font-size:10.5pt} .sug-r{margin:6px 0 0;color:#666;font-size:9.5pt}
 table{border-collapse:collapse;width:100%;margin:10px 0;font-size:9pt}
 th,td{border:1px solid #ccc;padding:6px;vertical-align:top;text-align:left} th{background:#021D44;color:#fff}
 .exec{background:#F2F5FA;border-left:4px solid #021D44;padding:10px 14px;margin:10px 0;font-size:10.5pt}
 .nota{margin-top:20px;color:#666;font-size:9pt;font-style:italic}
</style></head><body>
 <h1>Analise Comparativa de Contrato</h1>
 <p style="color:#555;margin:0 0 6px">${esc(modeloNome)}</p>
 ${dados.resumo_executivo?`<div class="exec">${esc(dados.resumo_executivo)}</div>`:''}
 <h2>📚 Divergencias (analise clausula a clausula)</h2>
 ${blocos || '<p>Nenhuma divergencia relevante identificada.</p>'}
 ${ausentesHtml}
 ${topo.length?`<h2>📊 Resumo visual (prioridade por severidade)</h2><table><thead><tr><th>Tema</th><th>Contrato do Cliente</th><th>Modelo BMS</th><th>Severidade</th><th>Impacto</th><th>Sugestao</th></tr></thead><tbody>${rows}</tbody></table>`:''}
 ${dados.observacoes?`<p><b>Observacoes:</b> ${esc(dados.observacoes)}</p>`:''}
 <p class="nota">Este relatorio tem carater informativo e nao substitui consulta juridica individualizada.</p>
</body></html>`;

return [{ json: { analise_md, html } }];

